WITH `t0` AS (SELECT `tenantId`, `entityId`, `version`, `effectiveAt`, `insertedAt`, `price_change_log_sum`, `price_change_count`, `stock_index`, `stock_index_warnings`, `lead_time_index_part_days`, `lead_time_index_part_count`, `lead_time_max_days` FROM `metric_group_ots_component_indices` FINAL WHERE `tenantId` = {p0:String})
SELECT `m`.`tenantId` AS `tenantId`, `m`.`entityId` AS `entityId`, `m`.`version` AS `version`, `m`.`effectiveAt` AS `effectiveAt`, `m`.`insertedAt` AS `insertedAt`, `m`.`price_change_log_sum` AS `price_change_log_sum`, `m`.`price_change_count` AS `price_change_count`, `m`.`stock_index` AS `stock_index`, `m`.`stock_index_warnings` AS `stock_index_warnings`, `m`.`lead_time_index_part_days` AS `lead_time_index_part_days`, `m`.`lead_time_index_part_count` AS `lead_time_index_part_count`, `m`.`lead_time_max_days` AS `lead_time_max_days`
FROM `t0` AS `m`
INNER ALL JOIN (SELECT `tenantId`, `entityId`, max(`version`) AS `version` FROM `t0` GROUP BY `tenantId`, `entityId`) AS `v` ON `m`.`tenantId` = `v`.`tenantId` AND `m`.`entityId` = `v`.`entityId` AND `m`.`version` = `v`.`version`
